import multiprocessing as mp


def 翻倍(位子, 下标, 数):
    位子[下标] = 数 * 2


if __name__ == '__main__':
    n = {n}
    起点 = []
    for _ in range(n):
        起点.append(int(input()))
    位子 = mp.Array('i', n)
    孩子们 = []
    for i in range(n):
        p = mp.Process(target=翻倍, args=(位子, i, 起点[i]))
        p.start()
        孩子们.append(p)
    for p in 孩子们:
        p.join()
    for i in range(n):
        print(位子[i])
